package in.carenest.clinic.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.http.HttpMethod; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.filter.OncePerRequestFilter;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import javax.crypto.SecretKey; import java.io.IOException; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*;
@Configuration public class SecurityConfig {
 @Bean JwtService jwtService(@Value("${app.jwt-secret}") String secret,@Value("${app.jwt-minutes}") long minutes){return new JwtService(secret,minutes);}
 @Bean SecurityFilterChain chain(HttpSecurity h,JwtService jwt)throws Exception{return h.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/login","/api/public/receipts/**","/actuator/health").permitAll().requestMatchers(HttpMethod.POST,"/api/admin/clinics").hasRole("PLATFORM_ADMIN").requestMatchers(HttpMethod.GET,"/api/availability/**","/api/slots/**").authenticated().requestMatchers("/api/appointments/**").hasAnyRole("OWNER","RECEPTIONIST").requestMatchers("/api/partners/**","/api/settings/**").hasAnyRole("OWNER","PLATFORM_ADMIN").anyRequest().authenticated()).addFilterBefore(new JwtFilter(jwt),UsernamePasswordAuthenticationFilter.class).build();}
 static class JwtFilter extends OncePerRequestFilter {private final JwtService jwt; JwtFilter(JwtService j){jwt=j;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var x=jwt.parse(h.substring(7));var p=new TenantPrincipal(UUID.fromString(x.getSubject()),x.get("clinic",String.class)==null?null:UUID.fromString(x.get("clinic",String.class)),x.get("branch",String.class)==null?null:UUID.fromString(x.get("branch",String.class)),x.get("role",String.class),x.get("name",String.class));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(p,null,List.of(new SimpleGrantedAuthority("ROLE_"+p.role()))));}catch(Exception ignored){}c.doFilter(r,s);}}
 public record TenantPrincipal(UUID userId,UUID clinicId,UUID branchId,String role,String name){}
 public static class JwtService {private final SecretKey key;private final long minutes;JwtService(String s,long m){key=Keys.hmacShaKeyFor(s.getBytes(StandardCharsets.UTF_8));minutes=m;} public String issue(TenantPrincipal p){var b=Jwts.builder().subject(p.userId().toString()).claim("clinic",p.clinicId()==null?null:p.clinicId().toString()).claim("branch",p.branchId()==null?null:p.branchId().toString()).claim("role",p.role()).claim("name",p.name()).issuedAt(new Date()).expiration(Date.from(Instant.now().plus(Duration.ofMinutes(minutes))));return b.signWith(key).compact();} public Claims parse(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload();}}
}
